`src/cortex.zig`
```zig
const std = @import("std");
const config = @import("config.zig");

pub const Synapse = struct {
    target: u32,
    strength: u8,
};

pub const Neuron = struct {
    outgoing_synapses: [config.SYNAPSES_PER_NEURON]Synapse = std.mem.zeroes([config.SYNAPSES_PER_NEURON]Synapse),
    activation_level: u16 = 0,
    refractory_timer: u16 = 0,
    is_inhibitory: bool = false,
    last_fired_cycle: u64 = 0,
};

pub const Cortex = struct {
    const Self = @This();
    const NeuronSlice = []Neuron;
    const NeuronPtr = *Neuron;

    memory: [config.CORTEX_SIZE_BYTES]u8 align(@alignOf(Neuron)) = std.mem.zeroes([config.CORTEX_SIZE_BYTES]u8),
    neuron_slice: NeuronSlice,
    allocator: CortexAllocator,
    rng_state: u32 = 1,
    cycle_count: u64 = 0,
    active_neurons_indices: [MAX_NEURONS]u32 = std.mem.zeroes([MAX_NEURONS]u32),
    active_neurons_count: usize = 0,
    context_buffer: [config.CONTEXT_WINDOW_SIZE]u32 = std.mem.zeroes([config.CONTEXT_WINDOW_SIZE]u32),
    context_index: usize = 0,
    learning_rate_multiplier: u8 = 1,

    pub fn init() Self {
        const neuron_count = config.CORTEX_SIZE_BYTES / @sizeOf(Neuron);
        const slice = std.mem.bytesAsSlice(Neuron, memory[0..neuron_count * @sizeOf(Neuron)]);
        var cortex = Self{
            .neuron_slice = slice,
            .allocator = CortexAllocator.init(),
        };
        var i: usize = 0;
        while (i < neuron_count) {
            cortex.neuron_slice[i].is_inhibitory = cortex.nextRandomFloat() < config.INHIBITORY_NEURON_RATIO;
            i += 1;
        }
        return cortex;
    }

    pub const CortexAllocator = struct {
        const Allocator = std.mem.Allocator;
        const Inner = @This();

        offset: usize = 0,

        pub fn init() Inner {
            return Inner{ .offset = @sizeOf(Cortex) };
        }

        pub fn allocator(self: *Inner) Allocator {
            return Allocator{
                .ptr = self,
                .vtable = &.{
                    .alloc = alloc,
                    .resize = resize,
                    .free = free,
                },
            };
        }

        fn alloc(ctx: *anyopaque, len: usize, log2_ptr_align: u8, ret_addr: usize) ?[*]u8 {
            _ = log2_ptr_align;
            _ = ret_addr;
            const self: *Inner = @ptrCast(@alignCast(ctx));
            if (self.offset + len > config.CORTEX_SIZE_BYTES) return null;
            const result = config.memory[self.offset .. self.offset + len];
            self.offset += len;
            return result.ptr;
        }

        fn resize(ctx: *anyopaque, buf: []u8, log2_buf_align: u8, new_len: usize, ret_addr: usize) bool {
            _ = ctx;
            _ = buf;
            _ = log2_buf_align;
            _ = new_len;
            _ = ret_addr;
            return false;
        }

        fn free(ctx: *anyopaque, buf: []u8, log2_buf_align: u8, ret_addr: usize) void {
            _ = ctx;
            _ = buf;
            _ = log2_buf_align;
            _ = ret_addr;
        }
    };

    pub fn getNeuron(self: *Self, index: u32) ?*Neuron {
        if (index >= self.neuron_slice.len) return null;
        return &self.neuron_slice[index];
    }

    pub fn addSynapse(self: *Self, source_idx: u32, target_idx: u32, strength: u8) bool {
        if (source_idx == target_idx) return false;
        if (source_idx >= self.neuron_slice.len or target_idx >= self.neuron_slice.len) return false;
        const source_neuron = self.getNeuron(source_idx) orelse return false;
        var i: usize = 0;
        while (i < config.SYNAPSES_PER_NEURON) {
            if (source_neuron.outgoing_synapses[i].strength == 0) {
                source_neuron.outgoing_synapses[i].target = target_idx;
                source_neuron.outgoing_synapses[i].strength = @min(strength * self.learning_rate_multiplier, 255);
                return true;
            }
            i += 1;
        }
        return false;
    }

    pub fn strengthenSynapse(self: *Self, source_idx: u32, target_idx: u32, amount: u8) void {
        const source_neuron = self.getNeuron(source_idx) orelse return;
        var i: usize = 0;
        while (i < config.SYNAPSES_PER_NEURON) {
            if (source_neuron.outgoing_synapses[i].target == target_idx and source_neuron.outgoing_synapses[i].strength > 0) {
                source_neuron.outgoing_synapses[i].strength = @min(source_neuron.outgoing_synapses[i].strength + amount, 255);
                return;
            }
            i += 1;
        }
        _ = self.addSynapse(source_idx, target_idx, amount);
    }

    pub fn activate(self: *Self, neuron_idx: u32, activation: u16) void {
        const neuron = self.getNeuron(neuron_idx) orelse return;
        if (neuron.refractory_timer > 0) return;
        neuron.activation_level = activation;
        neuron.last_fired_cycle = self.cycle_count;
        self.addToActiveList(neuron_idx);
        self.addToContext(neuron_idx);
    }

    fn addToActiveList(self: *Self, neuron_idx: u32) void {
        if (self.active_neurons_count < self.active_neurons_indices.len) {
            self.active_neurons_indices[self.active_neurons_count] = neuron_idx;
            self.active_neurons_count += 1;
        }
    }

    fn addToContext(self: *Self, neuron_idx: u32) void {
        self.context_buffer[self.context_index] = neuron_idx;
        self.context_index = (self.context_index + 1) % config.CONTEXT_WINDOW_SIZE;
    }

    pub fn nextRandom(self: *Self) u32 {
        self.rng_state = 1103515245 *% self.rng_state + 12345;
        return self.rng_state;
    }

    pub fn nextRandomFloat(self: *Self) f32 {
        return @as(f32, @floatFromInt(self.nextRandom())) / @as(f32, @floatFromInt(std.math.maxInt(u32)));
    }

    pub fn forgetCycle(self: *Self) void {
        var n_idx: usize = 0;
        while (n_idx < self.neuron_slice.len) {
            const neuron = &self.neuron_slice[n_idx];
            var s_idx: usize = 0;
            while (s_idx < config.SYNAPSES_PER_NEURON) {
                if (neuron.outgoing_synapses[s_idx].strength > 0) {
                    if (neuron.outgoing_synapses[s_idx].strength <= config.FORGET_RATE) {
                        neuron.outgoing_synapses[s_idx].strength = 0;
                        neuron.outgoing_synapses[s_idx].target = 0;
                    } else {
                        neuron.outgoing_synapses[s_idx].strength -= config.FORGET_RATE;
                    }
                }
                s_idx += 1;
            }
            n_idx += 1;
        }
    }

    pub fn refractoryCycle(self: *Self) void {
        var i: usize = 0;
        while (i < self.neuron_slice.len) {
            if (self.neuron_slice[i].refractory_timer > 0) {
                self.neuron_slice[i].refractory_timer -= 1;
            }
            i += 1;
        }
    }

    pub fn decayActivation(self: *Self) void {
        var i: usize = 0;
        while (i < self.neuron_slice.len) {
            if (self.neuron_slice[i].activation_level > 0) {
                self.neuron_slice[i].activation_level /= 2;
            }
            i += 1;
        }
        self.active_neurons_count = 0;
    }

    pub fn processActiveNeurons(self: *Self) void {
        var i: usize = 0;
        while (i < self.active_neurons_count) {
            const source_idx = self.active_neurons_indices[i];
            const source_neuron = self.getNeuron(source_idx) orelse continue;
            if (source_neuron.activation_level > config.MAX_ACTIVATION / 2) {
                source_neuron.refractory_timer = config.REFRACTORY_PERIOD_CYCLES;
                var s_idx: usize = 0;
                while (s_idx < config.SYNAPSES_PER_NEURON) {
                    const synapse = &source_neuron.outgoing_synapses[s_idx];
                    if (synapse.strength > 0) {
                        const target_neuron = self.getNeuron(synapse.target) orelse continue;
                        const signal_strength: u16 = @as(u16, synapse.strength) * source_neuron.activation_level / config.MAX_ACTIVATION;
                        if (source_neuron.is_inhibitory) {
                            if (target_neuron.activation_level > signal_strength) {
                                target_neuron.activation_level -= signal_strength;
                            } else {
                                target_neuron.activation_level = 0;
                            }
                        } else {
                            const new_activation = @addWithOverflow(target_neuron.activation_level, signal_strength);
                            target_neuron.activation_level = new_activation[0];
                            if (new_activation[1] > 0) {
                                target_neuron.activation_level = config.MAX_ACTIVATION;
                            }
                            if (target_neuron.activation_level > config.MAX_ACTIVATION / 3) {
                                self.addToActiveList(synapse.target);
                            }
                        }
                    }
                    s_idx += 1;
                }
            }
            i += 1;
        }
    }

    pub fn hebbianLearning(self: *Self) void {
        if (self.active_neurons_count < 2) return;
        var i: usize = 0;
        while (i < self.active_neurons_count) {
            const n1_idx = self.active_neurons_indices[i];
            var j: usize = i + 1;
            while (j < self.active_neurons_count) {
                const n2_idx = self.active_neurons_indices[j];
                self.strengthenSynapse(n1_idx, n2_idx, config.INITIAL_SYNAPSE_STRENGTH);
                self.strengthenSynapse(n2_idx, n1_idx, config.INITIAL_SYNAPSE_STRENGTH);
                j += 1;
            }
            i += 1;
        }
    }
};
