const std = @import("std");
const config = @import("config.zig");
const cortex = @import("cortex.zig");

pub fn readFileToBytes(path: []const u8, allocator: std.mem.Allocator) ![]u8 {
    const file = std.fs.cwd().openFile(path, .{}) catch |err| switch (err) {
        error.FileNotFound => {
            std.log.err("File not found: {s}", .{path});
            return err;
        },
        else => return err,
    };
    defer file.close();
    return file.readToEndAlloc(allocator, 1024 * 1024 * 1024);
}

pub fn visualizeCortex(cortex_instance: *cortex.Cortex) void {
    const stdout = std.io.getStdOut().writer();
    var i: usize = 0;
    while (i < config.VISUALIZER_HEIGHT) {
        var j: usize = 0;
        while (j < config.VISUALIZER_WIDTH) {
            const neuron_idx_float = @as(f64, @floatFromInt(i * config.VISUALIZER_WIDTH + j)) / @as(f64, @floatFromInt(config.VISUALIZER_WIDTH * config.VISUALIZER_HEIGHT));
            const neuron_idx = @as(u32, @intFromFloat(neuron_idx_float * @as(f64, @floatFromInt(cortex_instance.neuron_slice.len))));
            const neuron = cortex_instance.getNeuron(neuron_idx) orelse {
                stdout.print(" ", .{}) catch {};
                j += 1;
                continue;
            };
            const activation_f = @as(f32, @floatFromInt(neuron.activation_level)) / @as(f32, @floatFromInt(config.MAX_ACTIVATION));
            const char_idx = @as(usize, @intFromFloat(activation_f * @as(f32, @floatFromInt(config.VISUALIZER_CHARS.len - 1))));
            stdout.print("{c}", .{config.VISUALIZER_CHARS[@min(char_idx, config.VISUALIZER_CHARS.len - 1)]}) catch {};
            j += 1;
        }
        stdout.print("\n", .{}) catch {};
        i += 1;
    }
    stdout.print("Cycle: {}, Active: {}, LR: {}\n", .{ cortex_instance.cycle_count, cortex_instance.active_neurons_count, cortex_instance.learning_rate_multiplier }) catch {};
    stdout.print("Press 'r' for reward, 'd' for dream mode, 's' for sleep, 'q' to quit.\n", .{}) catch {};
}

pub fn handleUserInput(cortex_instance: *cortex.Cortex) bool {
    const stdin = std.io.getStdIn();
    var poller = std.io.poll(stdin);
    defer poller.deinit();

    poller.poll() catch |err| switch (err) {
        error.OperationWouldBlock => return true,
        else => return false,
    };

    if (poller.stdin.readable) {
        const buffer = poller.stdin.read(&[1]u8{0}) catch |err| switch (err) {
            error.EndOfStream => return false,
            else => return false,
        };
        switch (buffer[0]) {
            'r' => {
                var i: usize = 0;
                while (i < cortex_instance.active_neurons_count) {
                    const n_idx = cortex_instance.active_neurons_indices[i];
                    const n = cortex_instance.getNeuron(n_idx) orelse continue;
                    var s_idx: usize = 0;
                    while (s_idx < config.SYNAPSES_PER_NEURON) {
                        if (n.outgoing_synapses[s_idx].strength > 0) {
                            n.outgoing_synapses[s_idx].strength = @min(n.outgoing_synapses[s_idx].strength + 50, 255);
                        }
                        s_idx += 1;
                    }
                    i += 1;
                }
                cortex_instance.learning_rate_multiplier = @min(cortex_instance.learning_rate_multiplier + 10, 255);
            },
            'd' => {
                runDreamMode(cortex_instance);
            },
            's' => {
                runSleepPhase(cortex_instance);
            },
            'q' => {
                return false;
            },
            else => {},
        }
    }
    return true;
}

fn runDreamMode(cortex_instance: *cortex.Cortex) void {
    var i: usize = 0;
    while (i < config.DREAM_IMPULSE_COUNT) {
        const random_idx = cortex_instance.nextRandom() % @as(u32, @intCast(cortex_instance.neuron_slice.len));
        cortex_instance.activate(random_idx, config.MAX_ACTIVATION);
        runProcessingCycle(cortex_instance);
        i += 1;
    }
}

fn runSleepPhase(cortex_instance: *cortex.Cortex) void {
    var i: usize = 0;
    while (i < config.SLEEP_CYCLES) {
        cortex_instance.forgetCycle();
        cortex_instance.cycle_count += 1;
        i += 1;
        if (i % 1000 == 0) {
            const stdout = std.io.getStdOut().writer();
            stdout.print("Sleeping... {}/{}\n", .{ i, config.SLEEP_CYCLES }) catch {};
        }
    }
}

fn runProcessingCycle(cortex_instance: *cortex.Cortex) void {
    cortex_instance.processActiveNeurons();
    cortex_instance.hebbianLearning();
    cortex_instance.decayActivation();
    cortex_instance.forgetCycle();
    cortex_instance.refractoryCycle();
    cortex_instance.cycle_count += 1;
    if (cortex_instance.learning_rate_multiplier > 1) {
        cortex_instance.learning_rate_multiplier -= 1;
    }
}
