const std = @import("std");
const config = @import("config.zig");
const cortex = @import("cortex.zig");

const Cortex = cortex.Cortex;

fn hashInput(data: anytype, band: usize, seed_idx: usize) u32 {
    _ = band;
    const seed = config.HASH_SEEDS[0][seed_idx];
    var hash: u32 = seed;
    if (@TypeOf(data) == u32) {
        hash +%= data;
    } else if (@TypeOf(data) == u8) {
        hash +%= data;
    }
    hash ^= (hash >> 16);
    hash *%= 0x85ebca6b;
    hash ^= (hash >> 13);
    hash *%= 0xc2b2ae35;
    hash ^= (hash >> 16);
    return hash;
}

pub fn processInputByte(cortex_instance: *Cortex, byte: u8, last_byte_time: u32) void {
    var surprise = false;
    var predicted_activation_sum: u64 = 0;
    var i: usize = 0;
    while (i < cortex_instance.active_neurons_count) {
        predicted_activation_sum += cortex_instance.neuron_slice[cortex_instance.active_neurons_indices[i]].activation_level;
        i += 1;
    }

    var band: usize = 0;
    while (band < config.INPUT_BANDS) {
        const input_val = if (band == 0) @as(u32, byte) else last_byte_time;
        var seed_idx: usize = 0;
        while (seed_idx < 4) {
            const hashed_idx = hashInput(input_val, band, seed_idx) % @as(u32, @intCast(cortex_instance.neuron_slice.len));
            cortex_instance.activate(hashed_idx, config.MAX_ACTIVATION);
            seed_idx += 1;
        }
        band += 1;
    }

    var new_activation_sum: u64 = 0;
    i = 0;
    while (i < cortex_instance.active_neurons_count) {
        new_activation_sum += cortex_instance.neuron_slice[cortex_instance.active_neurons_indices[i]].activation_level;
        i += 1;
    }

    if (predicted_activation_sum > 0 and new_activation_sum < predicted_activation_sum / 2) {
        surprise = true;
    }

    if (surprise) {
        cortex_instance.learning_rate_multiplier = @min(cortex_instance.learning_rate_multiplier + config.LEARNING_RATE_BOOST, 255);
    }

    propagateToHigherCortex(cortex_instance);
}

pub fn propagateToHigherCortex(cortex_instance: *Cortex) void {
    const higher_start = @as(u32, @intCast(config.OUTPUT_AREA_START));
    if (cortex_instance.active_neurons_count == 0) return;

    const aggregated_input = cortex_instance.nextRandom();

    var seed_idx: usize = 0;
    while (seed_idx < 4) {
        const hashed_idx = higher_start + (hashInput(aggregated_input, 0, seed_idx) % (@as(u32, @intCast(config.OUTPUT_AREA_START))));
        if (hashed_idx < cortex_instance.neuron_slice.len) {
            cortex_instance.activate(hashed_idx, config.MAX_ACTIVATION / 2);
        }
        seed_idx += 1;
    }
}

pub fn processFeedback(cortex_instance: *Cortex) void {
    var i: usize = 0;
    while (i < cortex_instance.active_neurons_count) {
        const source_idx = cortex_instance.active_neurons_indices[i];
        const feedback_idx = hashInput(source_idx, 0, 1) % @as(u32, @intCast(config.OUTPUT_AREA_START));
        if (feedback_idx < cortex_instance.neuron_slice.len) {
            cortex_instance.activate(feedback_idx, config.MAX_ACTIVATION / 4);
        }
        i += 1;
    }
}

pub fn decodeOutput(cortex_instance: *Cortex) u8 {
    var max_activation: u16 = 0;
    var best_neuron_idx: u32 = 0;

    var i: usize = config.OUTPUT_AREA_START;
    while (i < cortex_instance.neuron_slice.len) {
        const neuron = &cortex_instance.neuron_slice[i];
        if (neuron.activation_level > max_activation) {
            max_activation = neuron.activation_level;
            best_neuron_idx = @as(u32, @intCast(i));
        }
        i += 1;
    }
    if (max_activation < config.MAX_ACTIVATION / 10) return 0;
    return @as(u8, @truncate(best_neuron_idx));
}
