const std = @import("std");
const config = @import("config.zig");
const cortex_mod = @import("cortex.zig");
const processing = @import("processing.zig");
const io = @import("io.zig");

const Cortex = cortex_mod.Cortex;
const gpa = std.heap.page_allocator;

pub fn main() !void {
    var cortex_instance = Cortex.init();
    var timer = try std.time.Timer.start();

    const args = try std.process.argsAlloc(gpa);
    defer std.process.argsFree(gpa, args);
    if (args.len < 2) {
        const stderr = std.io.getStdErr().writer();
        stderr.print("Usage: {s} <input_file.txt>\n", .{args[0]}) catch {};
        std.process.exit(1);
    }
    const file_path = args[1];

    const file_bytes = try io.readFileToBytes(file_path, gpa);
    defer gpa.free(file_bytes);

    var last_tick = timer.read();
    var last_byte_time: u32 = 0;

    var running = true;
    var byte_idx: usize = 0;
    var processing_input = true;
    var cycles_since_input: u64 = 0;

    while (running) {
        const now = timer.read();
        const delta = now - last_tick;
        last_tick = now;

        if (processing_input and byte_idx < file_bytes.len) {
            if (cycles_since_input > 0) {
                last_byte_time = @as(u32, @intCast(cycles_since_input));
            }
            processing.processInputByte(&cortex_instance, file_bytes[byte_idx], last_byte_time);
            byte_idx += 1;
            cycles_since_input = 0;
        } else {
            processing_input = false;
            cycles_since_input += 1;
            if (cycles_since_input % 100 == 0) {
                const random_idx = cortex_instance.nextRandom() % @as(u32, @intCast(cortex_instance.neuron_slice.len));
                cortex_instance.activate(random_idx, config.MAX_ACTIVATION / 8);
            }
        }

        cortex_instance.processActiveNeurons();
        cortex_instance.hebbianLearning();
        processing.processFeedback(&cortex_instance);

        const decoded_char = processing.decodeOutput(&cortex_instance);
        if (decoded_char > 0 and std.ascii.isPrint(decoded_char)) {
            const stdout = std.io.getStdOut().writer();
            stdout.print("{c}", .{decoded_char}) catch {};
        }

        cortex_instance.decayActivation();
        cortex_instance.forgetCycle();
        cortex_instance.refractoryCycle();

        cortex_instance.cycle_count += 1;
        if (cortex_instance.learning_rate_multiplier > 1) {
            cortex_instance.learning_rate_multiplier -= 1;
        }

        if (cortex_instance.cycle_count % 100 == 0) {
            const stdout = std.io.getStdOut().writer();
            stdout.print("\n", .{}) catch {};
            io.visualizeCortex(&cortex_instance);
            running = io.handleUserInput(&cortex_instance);
        }

        std.time.sleep(10 * std.time.ns_per_ms);
    }
}
