```zig
const std = @import("std");
const cortex = @import("cortex.zig");
const processing = @import("processing.zig");
const io = @import("io.zig");
const context = @import("context.zig");

const AGYKEREG_SIZE = 1024 * 1024 * 1024;
const NEURON_COUNT = AGYKEREG_SIZE / @sizeOf(cortex.Neuron);
const HIGHER_NEURON_COUNT = NEURON_COUNT / 10;
const MAX_ACTIVATIONS_PER_CYCLE = 1024;
const MAX_BEMENETI_MINTA = 1024;

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var agykerem = try cortex.Agykéreg.init(allocator, AGYKEREG_SIZE);
    defer agykerem.deinit(allocator);

    var felso_kereg = try cortex.Agykéreg.init(allocator, @sizeOf(cortex.Neuron) * HIGHER_NEURON_COUNT);
    defer felso_kereg.deinit(allocator);

    var bemeneti_kereg = io.InputCortex.init();
    var kimeneti_dekoder = io.OutputDecoder.init(allocator);
    defer kimeneti_dekoder.deinit();

    var vizualizalo = io.Visualizer.init(NEURON_COUNT);
    var aktualis_kontextus = context.Context.init(allocator);
    defer aktualis_kontextus.deinit();

    var aktiv_neuronok = try allocator.alloc(u32, MAX_ACTIVATIONS_PER_CYCLE);
    defer allocator.free(aktiv_neuronok);
    var aktiv_count: usize = 0;

    var bemeneti_minta = try allocator.alloc(u32, MAX_BEMENETI_MINTA);
    defer allocator.free(bemeneti_minta);

    var args = std.process.args();
    _ = args.skip();
    const input_file_path = args.next() orelse "input.txt";

    var file = std.fs.cwd().openFile(input_file_path, .{}) catch |err| {
        std.log.err("Nem sikerült megnyitni a fájlt: {}", .{err});
        return;
    };
    defer file.close();

    var bufferedReader = std.io.bufferedReader(file.reader());
    var reader = bufferedReader.reader();

    var byte_buffer: [128]u8 = undefined;
    var dream_mode = false;
    var reward_active = false;
    var sleep_phase = false;
    var cycle_count: u64 = 0;
    var elozo_aktiv_count: usize = 0;

    const stdout = std.io.getStdOut().writer();

    while (true) {
        cycle_count += 1;
        aktiv_count = 0;

        if (!dream_mode and !sleep_phase) {
            const bytes_read = try reader.read(&byte_buffer);
            if (bytes_read == 0) {
                dream_mode = true;
                try stdout.print("\n--- Bemenet vege. Atallas almodo modra. ---\n", .{});
            } else {
                var bemeneti_count = bemeneti_kereg.feldolgoz(byte_buffer[0..bytes_read], bemeneti_minta);
                for (bemeneti_minta[0..bemeneti_count]) |neuron_idx| {
                    if (neuron_idx < NEURON_COUNT and aktiv_count < MAX_ACTIVATIONS_PER_CYCLE) {
                        aktiv_neuronok[aktiv_count] = neuron_idx;
                        aktiv_count += 1;
                    }
                }
                try kimeneti_dekoder.tanul(allocator, byte_buffer[0..bytes_read], bemeneti_minta[0..bemeneti_count]);
            }
        } else if (dream_mode) {
            if (cycle_count % 200 == 0 and aktiv_count < MAX_ACTIVATIONS_PER_CYCLE) {
                const veletlen_neuron = @as(u32, @intCast((cycle_count * 31 + 17) % NEURON_COUNT));
                aktiv_neuronok[aktiv_count] = veletlen_neuron;
                aktiv_count += 1;
            }
        }

        if (cycle_count % 5000 == 0 and !dream_mode) {
            sleep_phase = true;
            dream_mode = false;
            try stdout.print("\n--- Alvasi fazis kezdodik. ---\n", .{});
        } else if (cycle_count % 5200 == 0 and sleep_phase) {
            sleep_phase = false;
            try stdout.print("\n--- Alvasi fazis veget ert. ---\n", .{});
        }

        processing.aktivaciosHullam(agykerem.neuronok, aktiv_neuronok[0..aktiv_count]);
        processing.hebbianTanulas(agykerem.neuronok, aktiv_neuronok[0..aktiv_count]);
        processing.felejtesiCiklus(agykerem.neuronok);
        processing.refrakterPeriodus(agykerem.neuronok);
        aktiv_count = processing.asszociativKereses(agykerem.neuronok, aktiv_neuronok[0..aktiv_count], MAX_ACTIVATIONS_PER_CYCLE);

        if (reward_active) {
            processing.jutalmazas(agykerem.neuronok);
            reward_active = false;
        }

        if (cycle_count % 10 == 0 and !dream_mode and !sleep_phase) {
            if (processing.meglepetesErzekel(aktiv_count, elozo_aktiv_count)) {
                std.log.warn("Meglepetes erzekelve! Novekvo plaszticitas.");
                reward_active = true;
            }
        }
        elozo_aktiv_count = aktiv_count;

        var felso_bemeneti_count: usize = 0;
        var felso_bemenet = try allocator.alloc(u32, aktiv_count);
        defer allocator.free(felso_bemenet);
        for (aktiv_neuronok[0..aktiv_count]) |n_idx| {
            if (agykerem.neuronok[n_idx].activation > 300) {
                const hash = processing.patternHasher(std.mem.asBytes(&n_idx));
                const felso_idx = hash % HIGHER_NEURON_COUNT;
                if (felso_bemeneti_count < aktiv_count) {
                    felso_bemenet[felso_bemeneti_count] = felso_idx;
                    felso_bemeneti_count += 1;
                }
            }
        }
        processing.aktivaciosHullam(felso_kereg.neuronok, felso_bemenet[0..felso_bemeneti_count]);
        processing.hebbianTanulas(felso_kereg.neuronok, felso_bemenet[0..felso_bemeneti_count]);
        processing.felejtesiCiklus(felso_kereg.neuronok);
        processing.refrakterPeriodus(felso_kereg.neuronok);

        try aktualis_kontextus.frissit(aktiv_neuronok[0..aktiv_count]);

        if (cycle_count % 20 == 0) {
            try vizualizalo.megjelenit(agykerem.neuronok, stdout);
        }

        const kimeneti_karakter = kimeneti_dekoder.dekodal(aktiv_neuronok[0..aktiv_count]);
        if (kimeneti_karakter) |c| {
            try stdout.print("{c}", .{c});
        }

        std.time.sleep(20 * std.time.ns_per_ms);
    }
}
