const std = @import("std");
const cortex = @import("cortex.zig");

pub fn patternHasher(data: []const u8) u32 {
    var hash: u32 = 5381;
    for (data) |byte| {
        hash = ((hash << 5) + hash) + byte;
    }
    return hash;
}

pub fn aktivaciosHullam(neuronok: []cortex.Neuron, aktiv_neuronok: []const u32) void {
    for (aktiv_neuronok) |idx| {
        if (idx < neuronok.len) {
            var neuron = &neuronok[idx];
            if (neuron.refractory_timer == 0) {
                if (neuron.is_inhibitory) {
                    neuron.activation = 0;
                } else {
                    neuron.activation = 1000;
                }
            }
        }
    }
}

pub fn hebbianTanulas(neuronok: []cortex.Neuron, aktiv_neuronok: []const u32) void {
    for (aktiv_neuronok) |i_idx| {
        if (i_idx >= neuronok.len) continue;
        var i_neuron = &neuronok[i_idx];
        if (i_neuron.is_inhibitory) continue;

        for (aktiv_neuronok) |j_idx| {
            if (i_idx == j_idx or j_idx >= neuronok.len) continue;
            var j_neuron = &neuronok[j_idx];
            if (j_neuron.is_inhibitory) continue;

            var found = false;
            for (i_neuron.synapses[0..i_neuron.synapse_count]) |*synapse| {
                if (synapse.target_index == j_idx) {
                    if (synapse.strength < 250) {
                        synapse.strength += 2;
                    }
                    found = true;
                    break;
                }
            }
            if (!found and i_neuron.synapse_count < i_neuron.synapses.len) {
                i_neuron.synapses[i_neuron.synapse_count] = .{ .target_index = j_idx, .strength = 10 };
                i_neuron.synapse_count += 1;
            }
        }
    }
}

pub fn felejtesiCiklus(neuronok: []cortex.Neuron) void {
    for (neuronok) |*neuron| {
        var write_idx: usize = 0;
        for (neuron.synapses[0..neuron.synapse_count]) |synapse| {
            if (synapse.strength > 1) {
                neuron.synapses[write_idx] = .{ .target_index = synapse.target_index, .strength = synapse.strength - 1 };
                write_idx += 1;
            }
        }
        neuron.synapse_count = @intCast(write_idx);
    }
}

pub fn refrakterPeriodus(neuronok: []cortex.Neuron) void {
    for (neuronok) |*neuron| {
        if (neuron.refractory_timer > 0) {
            neuron.refractory_timer -= 1;
        }
        if (neuron.activation > 0) {
            neuron.activation = @intCast(@max(0, @as(i32, neuron.activation) - 15));
            if (neuron.activation == 0) {
                neuron.refractory_timer = 5;
            }
        }
    }
}

pub fn asszociativKereses(neuronok: []cortex.Neuron, aktiv_neuronok: []const u32, max_capacity: usize) usize {
    var uj_aktivak = std.ArrayList(u32).init(std.heap.page_allocator);
    defer uj_aktivak.deinit();

    var current_activation_count = aktiv_neuronok.len;

    for (aktiv_neuronok) |idx| {
        if (idx >= neuronok.len) continue;
        const neuron = &neuronok[idx];
        for (neuron.synapses[0..neuron.synapse_count]) |synapse| {
            if (synapse.strength > 80) {
                uj_aktivak.append(synapse.target_index) catch continue;
            }
        }
    }

    for (uj_aktivak.items) |idx| {
        if (current_activation_count < max_capacity) {
            aktiv_neuronok[current_activation_count] = idx;
            current_activation_count += 1;
        }
    }
    return current_activation_count;
}

pub fn jutalmazas(neuronok: []cortex.Neuron) void {
    for (neuronok) |*neuron| {
        if (neuron.activation > 0 and !neuron.is_inhibitory) {
            for (neuron.synapses[0..neuron.synapse_count]) |*synapse| {
                if (synapse.strength < 245) {
                    synapse.strength += 10;
                }
            }
        }
    }
}

pub fn meglepetesErzekel(aktiv_count: usize, elozo_aktiv_count: usize) bool {
    const ratio: f64 = @as(f64, @floatFromInt(aktiv_count)) / @as(f64, @floatFromInt(elozo_aktiv_count));
    return ratio > 2.0 or ratio < 0.5;
}

pub fn fogalomkepzes(neuronok: []cortex.Neuron) void {
    _ = neuronok;
}
