const std = @import("std");
const cortex = @import("cortex.zig");
const processing = @import("processing.zig");

pub const InputCortex = struct {
    pub fn init() InputCortex {
        return InputCortex{};
    }

    pub fn feldolgoz(self: InputCortex, bytes: []const u8, output_buffer: []u32) usize {
        _ = self;
        var i: usize = 0;
        for (bytes, 0..) |byte, idx| {
            if (i >= output_buffer.len) break;
            output_buffer[i] = processing.patternHasher(&[_]u8{byte}) % 16000000;
            i += 1;

            if (idx > 0 and i < output_buffer.len) {
                output_buffer[i] = processing.patternHasher(&[_]u8{ bytes[idx - 1], byte }) % 16000000;
                i += 1;
            }
            if (idx > 1 and i < output_buffer.len) {
                output_buffer[i] = processing.patternHasher(&[_]u8{ bytes[idx - 2], bytes[idx - 1], byte }) % 16000000;
                i += 1;
            }
        }
        return i;
    }
};

const SortContext = struct {
    pub fn hash(self: @This(), s: []const u32) u64 {
        _ = self;
        var h: u64 = 0;
        for (s) |item| {
            h = h *% 31 + item;
        }
        return h;
    }
    pub fn eql(self: @This(), a: []const u32, b: []const u32) bool {
        _ = self;
        if (a.len != b.len) return false;
        for (a, 0..) |val_a, idx| {
            if (val_a != b[idx]) return false;
        }
        return true;
    }
};

pub const OutputDecoder = struct {
    const KarakterMap = std.HashMap([]const u32, u8, SortContext, 80);
    map: KarakterMap,

    pub fn init(allocator: std.mem.Allocator) OutputDecoder {
        return OutputDecoder{ .map = KarakterMap.init(allocator) };
    }

    pub fn deinit(self: *OutputDecoder) void {
        var it = self.map.iterator();
        while (it.next()) |entry| {
            self.map.allocator.free(entry.key_ptr.*);
        }
        self.map.deinit();
    }

    pub fn tanul(self: *OutputDecoder, allocator: std.mem.Allocator, bytes: []const u8, aktiv_neuronok: []const u32) !void {
        if (bytes.len == 0 or aktiv_neuronok.len == 0) return;
        const kulcs = try allocator.dupe(u32, aktiv_neuronok);
        std.sort.sort(u32, kulcs, {}, comptime std.sort.asc(u32));
        try self.map.put(kulcs, bytes[0]);
    }

    pub fn dekodal(self: *OutputDecoder, aktiv_neuronok: []const u32) ?u8 {
        if (aktiv_neuronok.len == 0) return null;
        var sorted_aktivak = try self.map.allocator.dupe(u32, aktiv_neuronok);
        defer self.map.allocator.free(sorted_aktivak);
        std.sort.sort(u32, sorted_aktivak, {}, comptime std.sort.asc(u32));

        if (self.map.get(sorted_aktivak)) |c| {
            return c;
        }
        return null;
    }
};

pub const Visualizer = struct {
    neuron_count: usize,
    width: usize,
    height: usize,

    pub fn init(neuron_count: usize) Visualizer {
        return Visualizer{
            .neuron_count = neuron_count,
            .width = 80,
            .height = 25,
        };
    }

    pub fn megjelenit(self: Visualizer, neuronok: []cortex.Neuron, writer: anytype) !void {
        const cell_size = @max(1, self.neuron_count / (self.width * self.height));
        _ = writer;
        var y: usize = 0;
        while (y < self.height) : (y += 1) {
            var x: usize = 0;
            while (x < self.width) : (x += 1) {
                const start_idx = (y * self.width + x) * cell_size;
                const end_idx = @min(start_idx + cell_size, self.neuron_count);
                var sum: u32 = 0;
                for (neuronok[start_idx..end_idx]) |neuron| {
                    sum += neuron.activation;
                }
                const avg = sum / cell_size;
                const char = if (avg > 500) '█' else if (avg > 300) '▓' else if (avg > 150) '▒' else if (avg > 50) '░' else ' ';
                try writer.print("{c}", .{char});
            }
            try writer.print("\n", .{});
        }
    }
};
