const std = @import("std");

pub const Context = struct {
    const AktivakListaja = std.ArrayList(u32);
    const KontextusTortenet = std.ArrayList(AktivakListaja);
    const MaxKontextusMéret = 20;

    allocator: std.mem.Allocator,
    tortenet: KontextusTortenet,

    pub fn init(allocator: std.mem.Allocator) Context {
        return Context{
            .allocator = allocator,
            .tortenet = KontextusTortenet.init(allocator),
        };
    }

    pub fn deinit(self: *Context) void {
        for (self.tortenet.items) |*lista| {
            lista.deinit();
        }
        self.tortenet.deinit();
    }

    pub fn frissit(self: *Context, aktiv_neuronok: []const u32) !void {
        var uj_lista = AktivakListaja.init(self.allocator);
        try uj_lista.appendSlice(aktiv_neuronok);
        try self.tortenet.append(uj_lista);
        if (self.tortenet.items.len > MaxKontextusMéret) {
            var regi_lista = self.tortenet.orderedRemove(0);
            regi_lista.deinit();
        }
    }

    pub fn getKornyezoMintak(self: Context) [][]const u32 {
        if (self.tortenet.items.len == 0) return &[_][]const u32{};
        const start = if (self.tortenet.items.len < 5) 0 else self.tortenet.items.len - 5;
        const slice = self.tortenet.items[start..];
        const result = self.allocator.alloc([]const u32, slice.len) catch return &[_][]const u32{};
        for (slice, 0..) |item, i| {
            result[i] = item.items;
        }
        return result;
    }
};
