const MIN_CONTEXT_LEN: usize = 0;
const MAX_NODES: usize = 10_000_000;
const ESCAPE_THRESHOLD: u32 = 2;
const TOP_K: usize = 50;
const MAX_GENERATION_LEN: usize = 1024;
const MAX_DOCUMENTS: usize = 1000;
const NGRAM_SIZE: comptime_int = 5;
const INVERTED_LIST_GROWTH: usize = 16;
const SERIALIZATION_VERSION: u32 = 1;

const Edge = struct {
    byte: u8,
    child_index: u32,
};

const Count = struct {
    byte: u8,
    count: u32,
};

const Node = struct {
    edges: []Edge = &.{},
    counts: []Count = &.{},
    total: u32 = 0,

    fn init(alloc: Allocator) !Node {
        return Node{};
    }

    fn deinit(self: *Node, alloc: Allocator) void {
        alloc.free(self.edges);
        alloc.free(self.counts);
        self.* = undefined;
    }

    fn findEdge(self: *const Node, byte: u8) ?u32 {
        const edges = self.edges;
        var lo: usize = 0;
        var hi: usize = edges.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const e = edges[mid];
            if (e.byte < byte) {
                lo = mid + 1;
            } else if (e.byte > byte) {
                hi = mid;
            } else {
                return e.child_index;
            }
        }
        return null;
    }

    fn findCount(self: *const Node, byte: u8) ?u32 {
        const counts = self.counts;
        var lo: usize = 0;
        var hi: usize = counts.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const c = counts[mid];
            if (c.byte < byte) {
                lo = mid + 1;
            } else if (c.byte > byte) {
                hi = mid;
            } else {
                return c.count;
            }
        }
        return null;
    }

    fn insertOrUpdateCount(self: *Node, alloc: Allocator, byte: u8, increment: u32) !void {
        var left: usize = 0;
        var right: usize = self.counts.len;
        while (left < right) {
            const mid = left + (right - left) / 2;
            if (self.counts[mid].byte < byte) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        if (left < self.counts.len and self.counts[left].byte == byte) {
            self.counts[left].count += increment;
            self.total += increment;
            return;
        }

        const new_counts = try alloc.alloc(Count, self.counts.len + 1);
        @memcpy(new_counts[0..left], self.counts[0..left]);
        new_counts[left] = Count{ .byte = byte, .count = increment };
        if (left < self.counts.len) {
            @memcpy(new_counts[left + 1 ..], self.counts[left..]);
        }
        alloc.free(self.counts);
        self.counts = new_counts;
        self.total += increment;
    }

    fn insertOrUpdateEdge(self: *Node, alloc: Allocator, byte: u8, child_index: u32) !void {
        var left: usize = 0;
        var right: usize = self.edges.len;
        while (left < right) {
            const mid = left + (right - left) / 2;
            if (self.edges[mid].byte < byte) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        if (left < self.edges.len and self.edges[left].byte == byte) {
            self.edges[left].child_index = child_index;
            return;
        }

        const new_edges = try alloc.alloc(Edge, self.edges.len + 1);
        @memcpy(new_edges[0..left], self.edges[0..left]);
        new_edges[left] = Edge{ .byte = byte, .child_index = child_index };
        if (left < self.edges.len) {
            @memcpy(new_edges[left + 1 ..], self.edges[left..]);
        }
        alloc.free(self.edges);
        self.edges = new_edges;
    }
};

nodes: []Node,
next_index: u32,
alloc: Allocator,
arena: std.heap.ArenaAllocator,
ngram_index: AutoHashMap([NGRAM_SIZE]u8, ArrayList(usize)),
documents: ArrayList(Document),
doc_positions: ArrayList(usize),
rng: std.rand.DefaultPrng,

pub const Document = struct {
    id: u32,
    content: []const u8,
};

pub fn init(allocator: Allocator) !ContextTrie {
    var arena = std.heap.ArenaAllocator.init(allocator);
    const alloc = arena.allocator();

    var nodes = try alloc.alloc(Node, 1);
    nodes[0] = try Node.init(alloc);

    var ngram_index = AutoHashMap([NGRAM_SIZE]u8, ArrayList(usize)).init(alloc);
    var documents = ArrayList(Document).init(alloc);
    var doc_positions = ArrayList(usize).init(alloc);

    return ContextTrie{
        .nodes = nodes,
        .next_index = 1,
        .alloc = alloc,
        .arena = arena,
        .ngram_index = ngram_index,
        .documents = documents,
        .doc_positions = doc_positions,
        .rng = std.rand.DefaultPrng.init(0),
    };
}

pub fn deinit(self: *ContextTrie) void {
    for (self.nodes) |*node| {
        node.deinit(self.alloc);
    }
    self.alloc.free(self.nodes);
    var it = self.ngram_index.iterator();
    while (it.next()) |entry| {
        entry.value_ptr.deinit();
    }
    self.ngram_index.deinit();
    self.doc_positions.deinit();
    self.arena.deinit();
    self.* = undefined;
}

fn newNode(self: *ContextTrie) !u32 {
    if (self.next_index >= MAX_NODES) return error.OutOfNodes;
    if (self.next_index >= self.nodes.len) {
        const new_len = std.math.min(self.nodes.len * 2, MAX_NODES);
        const new_nodes = try self.alloc.alloc(Node, new_len);
        @memcpy(new_nodes[0..self.nodes.len], self.nodes);
        for (new_nodes[self.nodes.len..]) |*node| {
            node.* = try Node.init(self.alloc);
        }
        self.nodes = new_nodes;
    }
    const idx = self.next_index;
    self.next_index += 1;
    return idx;
}

pub fn trainStep(self: *ContextTrie, context_window: []const u8, next_byte: u8) !void {
    const ctx_len = context_window.len;
    const effective_len = std.math.min(ctx_len, MAX_CONTEXT_LEN);

    var ctx_start: usize = if (ctx_len > MAX_CONTEXT_LEN) ctx_len - MAX_CONTEXT_LEN else 0;

    var node_idx: u32 = 0;
    var path: [MAX_CONTEXT_LEN]u32 = undefined;
    var depth: usize = 0;

    while (ctx_start <= ctx_len) : ({
        ctx_start += 1;
        depth += 1;
    }) {
        var current_node = &self.nodes[node_idx];
        try current_node.insertOrUpdateCount(self.alloc, next_byte, 1);

        if (ctx_start >= ctx_len) break;

        const byte = context_window[ctx_start];
        if (depth < effective_len) {
            if (current_node.findEdge(byte)) |child| {
                node_idx = child;
            } else {
                const new_idx = try self.newNode();
                try current_node.insertOrUpdateEdge(self.alloc, byte, new_idx);
                node_idx = new_idx;
            }
        }
    }
}

fn predictDistributionInternal(
    self: *ContextTrie,
    context: []const u8,
    buffer: *ArrayList(Count),
    seen_bytes: *std.AutoHashMap(u8, void),
) !void {
    var ctx_len = context.len;
    var ctx_start: usize = if (ctx_len > MAX_CONTEXT_LEN) ctx_len - MAX_CONTEXT_LEN else 0;

    while (true) {
        var node_idx: u32 = 0;
        var pos = ctx_start;
        while (pos < ctx_len) : (pos += 1) {
            const byte = context[pos];
            const node = &self.nodes[node_idx];
            if (node.findEdge(byte)) |child| {
                node_idx = child;
            } else {
                break;
            }
        } else {
            const node = &self.nodes[node_idx];
            const total = node.total;
            if (total > 0) {
                for (node.counts) |*count| {
                    if (!seen_bytes.contains(count.byte)) {
                        try buffer.append(Count{ .byte = count.byte, .count = count.count });
                        try seen_bytes.put(count.byte, {});
                    }
                }
            }
            return;
        }

        if (ctx_start >= context.len) break;
        ctx_start += 1;
    }

    return;
}

pub fn predictDistribution(
    self: *ContextTrie,
    context: []const u8,
    buffer: *ArrayList(Count),
) !void {
    buffer.clearRetainingCapacity();
    var seen_bytes = std.AutoHashMap(u8, void).init(self.alloc);
    defer seen_bytes.deinit();
    try self.predictDistributionInternal(context, buffer, &seen_bytes);
}

pub fn sampleNextByte(
    self: *ContextTrie,
    prompt: []const u8,
    temperature: f32,
    top_k: usize,
) !?u8 {
    var dist = ArrayList(Count).init(self.alloc);
    defer dist.deinit();

    try self.predictDistribution(prompt, &dist);
    if (dist.items.len == 0) return null;

    var total: f32 = 0.0;
    for (dist.items) |c| {
        const prob = @intToFloat(f32, c.count);
        const scaled = if (temperature > 0.001) std.math.pow(f32, prob, 1.0 / temperature) else 1.0;
        total += scaled;
    }

    if (total == 0.0) return dist.items[0].byte;

    const sorted = dist.items;
    var top_list = ArrayList(Count).init(self.alloc);
    defer top_list.deinit();

    for (sorted) |c| {
        const prob = @intToFloat(f32, c.count);
        const scaled = if (temperature > 0.001) std.math.pow(f32, prob, 1.0 / temperature) else 1.0;
        const norm = scaled / total;
        if (norm > 0) {
            try top_list.append(Count{
                .byte = c.byte,
                .count = @floatToInt(u32, norm * 1000000.0),
            });
        }
    }

    if (top_list.items.len == 0) return sorted[0].byte;

    const k = std.math.min(top_k, top_list.items.len);
    var cumulative: u32 = 0;
    for (top_list.items[0..k]) |*c| {
        cumulative += c.count;
        c.count = cumulative;
    }

    const r = @floatToInt(u32, self.rng.random().floatNorm(f32) * @intToFloat(f32, cumulative));
    for (top_list.items[0..k]) |c| {
        if (r < c.count) {
            return c.byte;
        }
    }
    return top_list.items[top_list.items.len - 1].byte;
}

pub fn loadCorpusFromFile(self: *ContextTrie, path: []const u8) !void {
    const file = try std.fs.cwd().openFile(path, .{ .mode = .read_only });
    defer file.close();

    var stream = std.io.bufferedReader(file.reader()).reader();
    var buf: [4096]u8 = undefined;

    var context_window = std.ArrayList(u8).init(self.alloc);
    defer context_window.deinit();

    while (try stream.readUntilDelimiterOrEof(&buf, '\n')) |line| {
        for (line) |byte| {
            if (byte == '\r') continue;
            if (byte < 32 and !std.ascii.isSpace(byte)) continue;

            const next_byte = byte;

            try self.trainStep(context_window.items, next_byte);

            try context_window.append(next_byte);

            while (context_window.items.len > MAX_CONTEXT_LEN) {
                _ = context_window.orderedRemove(0);
            }
        }

        try context_window.append('\n');
        while (context_window.items.len > MAX_CONTEXT_LEN) {
            _ = context_window.orderedRemove(0);
        }
    }
}

pub fn addDocument(self: *ContextTrie, id: u32, content: []const u8) !void {
    const new_id = @intCast(usize, self.documents.items.len);
    const doc = Document{ .id = id, .content = try self.alloc.dupe(u8, content) };
    try self.documents.append(doc);

    var i: usize = 0;
    while (i <= content.len - NGRAM_SIZE) : (i += 1) {
        var ngram: [NGRAM_SIZE]u8 = undefined;
        @memcpy(ngram[0..NGRAM_SIZE], content[i..][0..NGRAM_SIZE]);

        var list = try self.ngram_index.getOrPutValue(ngram, ArrayList(usize).init(self.alloc));
        try list.value_ptr.append(new_id);
    }

    try self.doc_positions.append(0);
}

fn scoreDocument(self: *ContextTrie, doc_id: usize, query: []const u8) u32 {
    var score: u32 = 0;
    const doc = self.documents.items[doc_id];
    var i: usize = 0;
    while (i <= query.len - NGRAM_SIZE) : (i += 1) {
        var ngram: [NGRAM_SIZE]u8 = undefined;
        @memcpy(ngram[0..NGRAM_SIZE], query[i..][0..NGRAM_SIZE]);
        if (self.ngram_index.get(ngram)) |*list| {
            for (list.items) |d| {
                if (d == doc_id) {
                    score += 1;
                }
            }
        }
    }
    return score;
}

pub fn retrieveSnippets(self: *ContextTrie, query: []const u8, count: usize) ![]const []const u8 {
    var scores = std.ArrayList(struct { id: usize, score: u32 }).init(self.alloc);
    defer scores.deinit();

    var i: usize = 0;
    while (i < self.documents.items.len) : (i += 1) {
        const s = self.scoreDocument(i, query);
        if (s > 0) {
            try scores.append(.{ .id = i, .score = s });
        }
    }

    std.mem.sort(struct { id: usize, score: u32 }, scores.items, {}, struct {
        fn cmp(ctx: void, a: @TypeOf(scores.items[0]), b: @TypeOf(scores.items[0])) bool {
            _ = ctx;
            return a.score > b.score;
        }
    }.cmp);

    const result_count = std.math.min(count, scores.items.len);
    const result = try self.alloc.alloc([]const u8, result_count);
    i = 0;
    while (i < result_count) : (i += 1) {
        result[i] = self.documents.items[scores.items[i].id].content;
    }
    return result;
}

pub fn generate(
    self: *ContextTrie,
    prompt: []const u8,
    max_len: usize,
    temperature: f32,
) ![]u8 {
    var output = try self.alloc.alloc(u8, 0);
    try output.ensureTotalCapacity(max_len);

    var context = try self.alloc.dupe(u8, prompt);
    defer self.alloc.free(context);

    var generated: usize = 0;
    while (generated < max_len) : (generated += 1) {
        const byte = try self.sampleNextByte(context, temperature, TOP_K);
        if (byte) |b| {
            try output.append(b);
            try context.append(b);

            while (context.len > MAX_CONTEXT_LEN) {
                _ = context[0];
                context = context[1..];
            }

            if (b == '\n') {
                const last = if (output.len >= 2) output[output.len - 2] else 0;
                if (last == '\n') break;
            }
        } else {
            break;
        }
    }

    return output;
}

pub fn serialize(self: *ContextTrie, writer: anytype) !void {
    try writer.writeInt(u32, SERIALIZATION_VERSION);
    try writer.writeInt(usize, self.next_index);
    try writer.writeInt(usize, self.documents.items.len);
    try writer.writeInt(usize, self.ngram_index.count());

    for (self.nodes[0..self.next_index]) |*node| {
        try writer.writeInt(usize, node.edges.len);
        for (node.edges) |e| {
            try writer.writeAll(&.{ e.byte });
            try writer.writeInt(u32, e.child_index);
        }
        try writer.writeInt(usize, node.counts.len);
        for (node.counts) |c| {
            try writer.writeAll(&.{ c.byte });
            try writer.writeInt(u32, c.count);
        }
        try writer.writeInt(u32, node.total);
    }

    for (self.documents.items) |doc| {
        try writer.writeInt(u32, doc.id);
        try writer.writeInt(usize, doc.content.len);
        try writer.writeAll(doc.content);
    }

    var entries = self.ngram_index.iterator();
    while (entries.next()) |entry| {
        try writer.writeAll(&entry.key_ptr.*);
        const list = entry.value_ptr.*;
        try writer.writeInt(usize, list.items.len);
        for (list.items) |pos| {
            try writer.writeInt(usize, pos);
        }
    }
}

pub fn deserialize(allocator: Allocator, reader: anytype) !ContextTrie {
    var arena = std.heap.ArenaAllocator.init(allocator);
    const alloc = arena.allocator();

    const version = try reader.readInt(u32);
    if (version != SERIALIZATION_VERSION) return error.InvalidVersion;

    const next_index = try reader.readInt(usize);
    const doc_count = try reader.readInt(usize);
    const index_count = try reader.readInt(usize);

    var nodes = try alloc.alloc(Node, next_index);
    for (nodes) |*node| {
        node.* = try Node.init(alloc);
    }

    var node_idx: usize = 0;
    while (node_idx < next_index) : (node_idx += 1) {
        const edge_count = try reader.readInt(usize);
        var edges = try alloc.alloc(Edge, edge_count);
        var i: usize = 0;
        while (i < edge_count) : (i += 1) {
            var byte: u8 = undefined;
            try reader.readNoEof(&byte);
            const child = try reader.readInt(u32);
            edges[i] = Edge{ .byte = byte, .child_index = child };
        }
        nodes[node_idx].edges = edges;

        const count_count = try reader.readInt(usize);
        var counts = try alloc.alloc(Count, count_count);
        i = 0;
        while (i < count_count) : (i += 1) {
            var byte: u8 = undefined;
            try reader.readNoEof(&byte);
            const cnt = try reader.readInt(u32);
            counts[i] = Count{ .byte = byte, .count = cnt };
        }
        nodes[node_idx].counts = counts;

        nodes[node_idx].total = try reader.readInt(u32);
    }

    var documents = ArrayList(Document).init(alloc);
    i = 0;
    while (i < doc_count) : (i += 1) {
        const id = try reader.readInt(u32);
        const len = try reader.readInt(usize);
        const content = try alloc.alloc(u8, len);
        try reader.readNoEof(content);
        try documents.append(.{ .id = id, .content = content });
    }

    var ngram_index = AutoHashMap([NGRAM_SIZE]u8, ArrayList(usize)).init(alloc);
    i = 0;
    while (i < index_count) : (i += 1) {
        var key: [NGRAM_SIZE]u8 = undefined;
        try reader.readNoEof(&key);
        const list_len = try reader.readInt(usize);
        var list = ArrayList(usize).init(alloc);
        var j: usize = 0;
        while (j < list_len) : (j += 1) {
            const pos = try reader.readInt(usize);
            try list.append(pos);
        }
        try ngram_index.put(key, list);
    }

    var doc_positions = ArrayList(usize).init(alloc);

    return ContextTrie{
        .nodes = nodes,
        .next_index = @intCast(u32, next_index),
        .alloc = alloc,
        .arena = arena,
        .ngram_index = ngram_index,
        .documents = documents,
        .doc_positions = doc_positions,
        .rng = std.rand.DefaultPrng.init(0),
    };
}

pub fn chatLoop(self: *ContextTrie, allocator: Allocator, writer: anytype, reader: anytype) !void {
    var buffer = std.ArrayList(u8).init(allocator);
    defer buffer.deinit();

    while (true) {
        try writer.writeAll("You: ");
        try writer.flush();
        buffer.clearRetainingCapacity();

        var line = try reader.readUntilDelimiterOrEofAlloc(allocator, '\n', 8192);
        if (line == null) break;
        const input = line.?;
        defer allocator.free(input);

        if (std.mem.eql(u8, input, "quit")) break;
        if (std.mem.eql(u8, input, "explain")) continue;

        try buffer.appendSlice(input);
        try buffer.append('\n');

        const snippets = try self.retrieveSnippets(input, 3);
        if (snippets.len == 0) {
            try writer.writeAll("Bot: ");
            const response = try self.generate(buffer.items, MAX_GENERATION_LEN, 0.8);
            try writer.writeAll(response);
            try writer.writeAll("\n\n");
        } else {
            try writer.writeAll("Bot: ");
            try writer.writeAll("[Reference]\n");
            for (snippets) |s| {
                try writer.writeAll(s);
                try writer.writeAll("\n");
            }
            try writer.writeAll("[/Reference]\n");
            const response = try self.generate(buffer.items, MAX_GENERATION_LEN, 0.8);
            try writer.writeAll(response);
            try writer.writeAll("\n\n");
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    var trie = try ContextTrie.init(alloc);
    defer trie.deinit();

    const corpus_exists = std.fs.cwd().openFile("corpus.txt", .{ .mode = .read_only }) catch false;
    if (corpus_exists) |_| {
        try trie.loadCorpusFromFile("corpus.txt");
    } else {
        const sample = 
            \\The quick brown fox jumps over the lazy dog.
            \\Hello world.
            \\This is a small corpus for testing.
            \\Zig is a general-purpose programming language.
            \\Memory safety without garbage collection.
            \\
        ;
        try std.fs.cwd().writeFile("corpus.txt", sample);
        try trie.loadCorpusFromFile("corpus.txt");
    }

    const model_file = try std.fs.cwd().createFile("model.bin", .{});
    defer model_file.close();
    try trie.serialize(model_file.writer());

    var stdin = std.io.getStdIn().reader();
    var stdout = std.io.getStdOut().writer();

    try trie.chatLoop(alloc, stdout, stdin);
}
