// src/main.zig
const std = @import("std");
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const AutoHashMap = std.AutoHashMap;
const File = std.fs.File;

const ContextTrie = @This();

const MAX_CONTEXT_LEN: usize = 32;
const MAX_NODES: usize = 10_000_000;
const TOP_K: usize = 50;
const MAX_GENERATION_LEN: usize = 1024;
const NGRAM_SIZE: comptime_int = 5;
const SERIALIZATION_VERSION: u32 = 1;

const Edge = struct {
    byte: u8,
    child_index: u32,
};

const Count = struct {
    byte: u8,
    count: u32,
};

const Node = struct {
    edges: ArrayList(Edge),
    counts: ArrayList(Count),
    total: u32,

    fn init(alloc: Allocator) !Node {
        return Node{
            .edges = ArrayList(Edge).init(alloc),
            .counts = ArrayList(Count).init(alloc),
            .total = 0,
        };
    }

    fn deinit(self: *Node) void {
        self.edges.deinit();
        self.counts.deinit();
        self.* = undefined;
    }

    fn findEdge(self: *const Node, byte: u8) ?u32 {
        for (self.edges.items) |e| {
            if (e.byte == byte) {
                return e.child_index;
            }
        }
        return null;
    }

    fn findCount(self: *const Node, byte: u8) ?u32 {
        for (self.counts.items) |c| {
            if (c.byte == byte) {
                return c.count;
            }
        }
        return null;
    }

    fn insertOrUpdateCount(self: *Node, byte: u8, increment: u32) !void {
        if (self.findCount(byte)) |count| {
            const index = for (self.counts.items, 0..) |c, i| {
                if (c.byte == byte) break i;
            } else unreachable;
            self.counts.items[index].count += increment;
        } else {
            try self.counts.append(.{ .byte = byte, .count = increment });
        }
        self.total += increment;
    }

    fn insertOrUpdateEdge(self: *Node, byte: u8, child_index: u32) !void {
        if (self.findEdge(byte)) |idx| {
            const edge_index = for (self.edges.items, 0..) |e, i| {
                if (e.byte == byte) break i;
            } else unreachable;
            self.edges.items[edge_index].child_index = child_index;
        } else {
            try self.edges.append(.{ .byte = byte, .child_index = child_index });
        }
    }
};

