pub fn init(allocator: Allocator) !ContextTrie {
    var nodes = ArrayList(Node).init(allocator);
    try nodes.append(try Node.init(allocator));

    var ngram_index = AutoHashMap([NGRAM_SIZE]u8, ArrayList(usize)).init(allocator);
    var documents = ArrayList(Document).init(allocator);

    return ContextTrie{
        .nodes = nodes,
        .alloc = allocator,
        .ngram_index = ngram_index,
        .documents = documents,
        .rng = std.rand.DefaultPrng.init(0),
    };
}

pub fn deinit(self: *ContextTrie) void {
    for (self.nodes.items) |*node| {
        node.deinit();
    }
    self.nodes.deinit();
    var it = self.ngram_index.iterator();
    while (it.next()) |entry| {
        entry.value_ptr.deinit();
    }
    self.ngram_index.deinit();
    for (self.documents.items) |doc| {
        self.alloc.free(doc.content);
    }
    self.documents.deinit();
    self.* = undefined;
}

fn newNode(self: *ContextTrie) !u32 {
    if (self.nodes.items.len >= MAX_NODES) return error.OutOfNodes;
    try self.nodes.append(try Node.init(self.alloc));
    return @intCast(u32, self.nodes.items.len - 1);
}

pub fn trainStep(self: *ContextTrie, context_window: []const u8, next_byte: u8) !void {
    const ctx_len = context_window.len;
    const effective_len = std.math.min(ctx_len, MAX_CONTEXT_LEN);

    var ctx_start: usize = if (ctx_len > MAX_CONTEXT_LEN) ctx_len - MAX_CONTEXT_LEN else 0;

    while (ctx_start <= ctx_len) : (ctx_start += 1) {
        var node_idx: u32 = 0;

        var pos = ctx_start;
        while (pos < ctx_len) : (pos += 1) {
            const byte = context_window[pos];
            const node = &self.nodes.items[node_idx];
            if (node.findEdge(byte)) |child| {
                node_idx = child;
            } else {
                const new_idx = try self.newNode();
                try node.insertOrUpdateEdge(byte, new_idx);
                node_idx = new_idx;
            }
        }

        const leaf_node = &self.nodes.items[node_idx];
        try leaf_node.insertOrUpdateCount(next_byte, 1);
    }
}

pub fn predictDistribution(
    self: *ContextTrie,
    context: []const u8,
    buffer: *ArrayList(Count),
) !void {
    buffer.clearRetainingCapacity();

    var seen_bytes = AutoHashMap(u8, void).init(self.alloc);
    defer seen_bytes.deinit();

    var ctx_len = context.len;
    var ctx_start: usize = if (ctx_len > MAX_CONTEXT_LEN) ctx_len - MAX_CONTEXT_LEN else 0;

    var full_path_found = false;
    while (ctx_start <= ctx_len) : (ctx_start += 1) {
        var node_idx: u32 = 0;
        var pos = ctx_start;
        while (pos < ctx_len) : (pos += 1) {
            const byte = context[pos];
            const node = &self.nodes.items[node_idx];
            if (node.findEdge(byte)) |child| {
                node_idx = child;
            } else {
                break;
            }
        } else {
            full_path_found = true;
        }

        const node = &self.nodes.items[node_idx];
        for (node.counts.items) |count| {
            if (!seen_bytes.contains(count.byte)) {
                try buffer.append(count);
                try seen_bytes.put(count.byte, {});
            }
        }

        if (full_path_found) break;
    }
}

pub fn sampleNextByte(
    self: *ContextTrie,
    prompt: []const u8,
    temperature: f32,
    top_k: usize,
) !?u8 {
    var dist = ArrayList(Count).init(self.alloc);
    defer dist.deinit();

    try self.predictDistribution(prompt, &dist);
    if (dist.items.len == 0) return null;

    const k = std.math.min(top_k, dist.items.len);
    if (k < dist.items.len) {
        std.mem.sort(Count, dist.items[0..dist.items.len], {}, struct {
            fn cmp(ctx: void, a: Count, b: Count) bool {
                _ = ctx;
                return a.count > b.count;
            }
        }.cmp);
    }

    var total: f64 = 0.0;
    var weights = try self.alloc.alloc(f64, k);
    defer self.alloc.free(weights);
    for (dist.items[0..k]) |count, i| {
        const prob = @intToFloat(f64, count.count);
        const scaled = if (temperature > 0.001) std.math.pow(f64, prob, 1.0 / temperature) else 1.0;
        weights[i] = scaled;
        total += scaled;
    }

    if (total == 0.0) return dist.items[0].byte;

    const r = self.rng.random().float(f64) * total;
    var cumulative: f64 = 0.0;
    for (dist.items[0..k], 0..) |count, i| {
        cumulative += weights[i];
        if (r < cumulative) {
            return count.byte;
        }
    }
    return dist.items[k - 1].byte;
}

pub fn loadCorpusFromFile(self: *ContextTrie, path: []const u8) !void {
    const file = try std.fs.cwd().openFile(path, .{ .mode = .read_only });
    defer file.close();

    var stream = std.io.bufferedReader(file.reader()).reader();
    var buf: [4096]u8 = undefined;

    var context_window = ArrayList(u8).init(self.alloc);
    defer context_window.deinit();

    while (try stream.readUntilDelimiterOrEof(&buf, '\n')) |line| {
        for (line) |byte| {
            if (byte == '\r') continue;
            if (byte < 32 and !std.ascii.isSpace(byte)) continue;

            const next_byte = byte;

            try self.trainStep(context_window.items, next_byte);
            try context_window.append(next_byte);

            while (context_window.items.len > MAX_CONTEXT_LEN) {
                _ = context_window.orderedRemove(0);
            }
        }

        try context_window.append('\n');
        while (context_window.items.len > MAX_CONTEXT_LEN) {
            _ = context_window.orderedRemove(0);
        }
    }
}

pub fn addDocument(self: *ContextTrie, id: u32, content: []const u8) !void {
    if (content.len < NGRAM_SIZE) {
        const doc = Document{ .id = id, .content = try self.alloc.dupe(u8, content) };
        try self.documents.append(doc);
        return;
    }

    const doc = Document{ .id = id, .content = try self.alloc.dupe(u8, content) };
    try self.documents.append(doc);

    var i: usize = 0;
    while (i <= content.len - NGRAM_SIZE) : (i += 1) {
        var ngram: [NGRAM_SIZE]u8 = undefined;
        @memcpy(ngram[0..NGRAM_SIZE], content[i..][0..NGRAM_SIZE]);

        var list = try self.ngram_index.getOrPutValue(ngram, ArrayList(usize).init(self.alloc));
        try list.value_ptr.append(self.documents.items.len - 1);
    }
}

fn scoreDocument(self: *ContextTrie, doc_id: usize, query: []const u8) u32 {
    if (query.len < NGRAM_SIZE) return 0;

    var score: u32 = 0;
    const doc = self.documents.items[doc_id];
    var i: usize = 0;
    while (i <= query.len - NGRAM_SIZE) : (i += 1) {
        var ngram: [NGRAM_SIZE]u8 = undefined;
        @memcpy(ngram[0..NGRAM_SIZE], query[i..][0..NGRAM_SIZE]);
        if (self.ngram_index.get(ngram)) |*list| {
            for (list.items) |d| {
                if (d == doc_id) {
                    score += 1;
                }
            }
        }
    }
    return score;
}

pub fn retrieveSnippets(self: *ContextTrie, allocator: Allocator, query: []const u8, count: usize) ![]const []const u8 {
    var scores = ArrayList(struct { id: usize, score: u32 }).init(allocator);
    defer scores.deinit();

    var i: usize = 0;
    while (i < self.documents.items.len) : (i += 1) {
        const s = self.scoreDocument(i, query);
        if (s > 0) {
            try scores.append(.{ .id = i, .score = s });
        }
    }

    std.mem.sort(struct { id: usize, score: u32 }, scores.items, {}, struct {
        fn cmp(ctx: void, a: @TypeOf(scores.items[0]), b: @TypeOf(scores.items[0])) bool {
            _ = ctx;
            return a.score > b.score;
        }
    }.cmp);

    const result_count = std.math.min(count, scores.items.len);
    const result = try allocator.alloc([]const u8, result_count);
    i = 0;
    while (i < result_count) : (i += 1) {
        result[i] = self.documents.items[scores.items[i].id].content;
    }
    return result;
}

pub fn generate(
    self: *ContextTrie,
    prompt: []const u8,
    max_len: usize,
    temperature: f32,
) ![]u8 {
    var output = ArrayList(u8).init(self.alloc);
    defer output.deinit();

    var context = ArrayList(u8).init(self.alloc);
    defer context.deinit();
    try context.appendSlice(prompt);

    var generated: usize = 0;
    while (generated < max_len) : (generated += 1) {
        const byte = try self.sampleNextByte(context.items, temperature, TOP_K);
        if (byte) |b| {
            try output.append(b);
            try context.append(b);

            while (context.items.len > MAX_CONTEXT_LEN) {
                _ = context.orderedRemove(0);
            }

            if (b == '\n') {
                const last = if (output.items.len >= 2) output.items[output.items.len - 2] else 0;
                if (last == '\n') break;
            }
        } else {
            break;
        }
    }

    return try self.alloc.dupe(u8, output.items);
}

pub fn serialize(self: *ContextTrie, writer: anytype) !void {
    try writer.writeInt(u32, SERIALIZATION_VERSION);
    try writer.writeInt(usize, self.nodes.items.len);
    try writer.writeInt(usize, self.documents.items.len);
    try writer.writeInt(usize, self.ngram_index.count());

    for (self.nodes.items) |*node| {
        try writer.writeInt(usize, node.edges.items.len);
        for (node.edges.items) |e| {
            try writer.writeAll(&.{ e.byte });
            try writer.writeInt(u32, e.child_index);
        }
        try writer.writeInt(usize, node.counts.items.len);
        for (node.counts.items) |c| {
            try writer.writeAll(&.{ c.byte });
            try writer.writeInt(u32, c.count);
        }
        try writer.writeInt(u32, node.total);
    }

    for (self.documents.items) |doc| {
        try writer.writeInt(u32, doc.id);
        try writer.writeInt(usize, doc.content.len);
        try writer.writeAll(doc.content);
    }

    var entries = self.ngram_index.iterator();
    while (entries.next()) |entry| {
        try writer.writeAll(&entry.key_ptr.*);
        const list = entry.value_ptr.*;
        try writer.writeInt(usize, list.items.len);
        for (list.items) |pos| {
            try writer.writeInt(usize, pos);
        }
    }
}

pub fn deserialize(allocator: Allocator, reader: anytype) !ContextTrie {
    const version = try reader.readInt(u32);
    if (version != SERIALIZATION_VERSION) return error.InvalidVersion;

    const node_count = try reader.readInt(usize);
    const doc_count = try reader.readInt(usize);
    const index_count = try reader.readInt(usize);

    var nodes = ArrayList(Node).init(allocator);
    try nodes.ensureTotalCapacity(node_count);
    for (0..node_count) |_| {
        const edge_count = try reader.readInt(usize);
        var edges = ArrayList(Edge).init(allocator);
        try edges.ensureTotalCapacity(edge_count);
        var i: usize = 0;
        while (i < edge_count) : (i += 1) {
            var byte: u8 = undefined;
            try reader.readNoEof(&byte);
            const child = try reader.readInt(u32);
            try edges.append(.{ .byte = byte, .child_index = child });
        }

        const count_count = try reader.readInt(usize);
        var counts = ArrayList(Count).init(allocator);
        try counts.ensureTotalCapacity(count_count);
        i = 0;
        while (i < count_count) : (i += 1) {
            var byte: u8 = undefined;
            try reader.readNoEof(&byte);
            const cnt = try reader.readInt(u32);
            try counts.append(.{ .byte = byte, .count = cnt });
        }

        const total = try reader.readInt(u32);
        try nodes.append(.{
            .edges = edges,
            .counts = counts,
            .total = total,
        });
    }

    var documents = ArrayList(Document).init(allocator);
    try documents.ensureTotalCapacity(doc_count);
    i = 0;
    while (i < doc_count) : (i += 1) {
        const id = try reader.readInt(u32);
        const len = try reader.readInt(usize);
        const content = try allocator.alloc(u8, len);
        try reader.readNoEof(content);
        try documents.append(.{ .id = id, .content = content });
    }

    var ngram_index = AutoHashMap([NGRAM_SIZE]u8, ArrayList(usize)).init(allocator);
    i = 0;
    while (i < index_count) : (i += 1) {
        var key: [NGRAM_SIZE]u8 = undefined;
        try reader.readNoEof(&key);
        const list_len = try reader.readInt(usize);
        var list = ArrayList(usize).init(allocator);
        try list.ensureTotalCapacity(list_len);
        var j: usize = 0;
        while (j < list_len) : (j += 1) {
            const pos = try reader.readInt(usize);
            try list.append(pos);
        }
        try ngram_index.put(key, list);
    }

    return ContextTrie{
        .nodes = nodes,
        .alloc = allocator,
        .ngram_index = ngram_index,
        .documents = documents,
        .rng = std.rand.DefaultPrng.init(0),
    };
}

pub fn chatLoop(self: *ContextTrie, allocator: Allocator) !void {
    const stdout = std.io.getStdOut().writer();
    const stdin = std.io.getStdIn().reader();

    var input_buffer = ArrayList(u8).init(allocator);
    defer input_buffer.deinit();

    while (true) {
        try stdout.writeAll("You: ");
        try stdout.flush();
        input_buffer.clearRetainingCapacity();

        const line = try stdin.readUntilDelimiterOrEofAlloc(allocator, '\n', 8192);
        if (line == null) break;
        defer allocator.free(line.?);

        if (std.mem.eql(u8, line.?, "quit")) break;

        try input_buffer.appendSlice(line.?);
        try input_buffer.append('\n');

        const snippets = try self.retrieveSnippets(allocator, input_buffer.items, 3);
        if (snippets.len == 0) {
            try stdout.writeAll("Bot: ");
            const response = try self.generate(input_buffer.items, MAX_GENERATION_LEN, 0.8);
            try stdout.writeAll(response);
            try stdout.writeAll("\n\n");
            allocator.free(response);
        } else {
            try stdout.writeAll("Bot: ");
            try stdout.writeAll("[Reference]\n");
            for (snippets) |s| {
                try stdout.writeAll(s);
                try stdout.writeAll("\n");
            }
            try stdout.writeAll("[/Reference]\n");
            const response = try self.generate(input_buffer.items, MAX_GENERATION_LEN, 0.8);
            try stdout.writeAll(response);
            try stdout.writeAll("\n\n");
            allocator.free(response);
            allocator.free(snippets);
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const alloc = gpa.allocator();

    var trie = try ContextTrie.init(alloc);
    defer trie.deinit();

    const corpus_exists = std.fs.cwd().openFile("corpus.txt", .{ .mode = .read_only }) catch false;
    if (corpus_exists) |_| {
        try trie.loadCorpusFromFile("corpus.txt");
    } else {
        const sample = 
            \\The quick brown fox jumps over the lazy dog.
            \\Hello world.
            \\This is a small corpus for testing.
            \\Zig is a general-purpose programming language.
            \\Memory safety without garbage collection.
            \\
        ;
        try std.fs.cwd().writeFile("corpus.txt", sample);
        try trie.loadCorpusFromFile("corpus.txt");
    }

    const model_file = try std.fs.cwd().createFile("model.bin", .{});
    defer model_file.close();
    try trie.serialize(model_file.writer());

    try trie.chatLoop(alloc);
}
